/bin/bash -lc "python - <<'PY'
import os, requests
from pathlib import Path
key=Path(os.environ['GALAXY_API_KEY_FILE']).read_text().strip()
base='https://usegalaxy.org'
ids={'res_1vs97':'f9cad7b01a4721356e9c7148e716decd','res_1vs98':'f9cad7b01a472135cb62a5bb95860ce4'}
targets={'PA14_19130','PA14_45940','PA14_35160'}
for label,did in ids.items():
    u=f'{base}/api/datasets/{did}/display'
    resp=requests.get(u,params={'key':key},timeout=60)
    resp.raise_for_status()
    print(label)
    for line in resp.text.splitlines():
        if line.split('\\t',1)[0] in targets:
            print(line)
PY"
